const PERSIAN_ZERO=1776,ARABIC_ZERO=1632;export function toLatinDigits(e){return String(e).replace(/[۰-۹٠-٩]/g,e=>{const t=e.charCodeAt(0);return String(t-(t>=PERSIAN_ZERO?PERSIAN_ZERO:ARABIC_ZERO))})}export function toPersianDigits(e){return String(e).replace(/[0-9]/g,e=>String.fromCharCode(PERSIAN_ZERO+Number(e)))}export function digitsOnly(e){return toLatinDigits(e).replace(/[^0-9]/g,"")}export function groupFour(e){return String(e).replace(/(.{4})(?=.)/g,"$1 ")}export function luhnValid(e){if(!/^[0-9]+$/.test(e))return!1;let t=0;for(let n=0;n<e.length;n++){let s=e.charCodeAt(e.length-1-n)-48;n%2===1&&(s*=2,s>9&&(s-=9)),t+=s}return t%10===0}export const CARD_LENGTH=16;export function checkCard(e){const t=digitsOnly(e).slice(0,CARD_LENGTH);return t?t.length<CARD_LENGTH?{digits:t,state:"short"}:{digits:t,state:luhnValid(t)?"valid":"luhn"}:{digits:t,state:"empty"}}export const IBAN_DIGITS=24;export function ibanDigits(e){const t=toLatinDigits(e).toUpperCase().replace(/^\s*IR/,"");return t.replace(/[^0-9]/g,"").slice(0,IBAN_DIGITS)}export function ibanMod97(e){const n=e.slice(4)+e.slice(0,4);let t=0;for(const e of n){const s=e>="A"&&e<="Z"?String(e.charCodeAt(0)-55):e;for(const e of s)t=(t*10+(e.charCodeAt(0)-48))%97}return t}export function checkIban(e){const t=ibanDigits(e),n=t?"IR"+t:"";return t?t.length<IBAN_DIGITS?{iban:n,state:"short"}:{iban:n,state:ibanMod97(n)===1?"valid":"checksum"}:{iban:n,state:"empty"}}export function ibanBankCode(e){return/^IR[0-9]{5}/.test(e)?e.slice(4,7):null}export function ibanCheckDigits(e){const t=ibanMod97("IR00"+e);return String(98-t).padStart(2,"0")}